import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextInt()) return;

        int n = sc.nextInt();
        final int MAX_ID = 101;

        long[] totalResponseTime = new long[MAX_ID];
        long[] receiveTime = new long[MAX_ID];
        boolean[] pending = new boolean[MAX_ID];
        boolean[] seen = new boolean[MAX_ID];

        long currentTime = 0;
        long nextDelay = 1;
        boolean hasEvent = false;

        for (int i = 0; i < n; i++) {
            String type = sc.next();
            int x = sc.nextInt();

            if (type.equals("T")) {
                nextDelay = x;
            } else {
                if (!hasEvent) {
                    hasEvent = true;
                    currentTime = 0;
                } else {
                    currentTime += nextDelay;
                }
                nextDelay = 1;

                if (type.equals("R")) {
                    seen[x] = true;
                    receiveTime[x] = currentTime;
                    pending[x] = true;
                } else { // type.equals("E")
                    seen[x] = true;
                    if (pending[x]) {
                        totalResponseTime[x] += currentTime - receiveTime[x];
                        pending[x] = false;
                    }
                }
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int id = 1; id <= 100; id++) {
            if (seen[id]) {
                long answer = pending[id] ? -1 : totalResponseTime[id];
                sb.append(id).append(' ').append(answer).append('\n');
            }
        }

        System.out.print(sb.toString());
    }
}
